// Component names assumed from @jinx-ui/react: Stepper/Step, Card, Stack, Field, Input, Text, Button.
// Adjust the imports if the actual export names in your version differ.
import { useCallback, useMemo, useState } from 'react';
import {
  Button,
  Card,
  Field,
  Input,
  Stack,
  Stepper,
  Step,
  Text,
} from '@jinx-ui/react';

type RegistrationValues = {
  name: string;
  email: string;
  phone: string;
  country: string;
  city: string;
  street: string;
  zip: string;
};

type RegistrationWizardProps = {
  onSubmit: (values: RegistrationValues) => void;
  initialValues?: Partial<RegistrationValues>;
};

const EMPTY: RegistrationValues = {
  name: '',
  email: '',
  phone: '',
  country: '',
  city: '',
  street: '',
  zip: '',
};

const STEPS = ['Контакты', 'Адрес', 'Проверка'] as const;

function RegistrationWizard({ onSubmit, initialValues }: RegistrationWizardProps) {
  const [step, setStep] = useState(0);
  const [values, setValues] = useState<RegistrationValues>({ ...EMPTY, ...initialValues });

  const setField = useCallback(
    (field: keyof RegistrationValues) => (event: { target: { value: string } }) => {
      setValues((prev) => ({ ...prev, [field]: event.target.value }));
    },
    [],
  );

  const isLast = step === STEPS.length - 1;

  const summary = useMemo(
    () => [
      ['Имя', values.name],
      ['E-mail', values.email],
      ['Телефон', values.phone],
      ['Страна', values.country],
      ['Город', values.city],
      ['Улица, дом', values.street],
      ['Индекс', values.zip],
    ],
    [values],
  );

  return (
    <Card className="jx-card jx-p-lg" style={{ maxWidth: 'var(--jx-size-container-sm)' }}>
      <Stack direction="vertical" gap="lg">
        <Stepper activeStep={step} className="jx-stepper">
          {STEPS.map((label, index) => (
            <Step key={label} index={index} label={label} />
          ))}
        </Stepper>

        {step === 0 && (
          <Stack direction="vertical" gap="md">
            <Field label="Имя" htmlFor="reg-name">
              <Input id="reg-name" value={values.name} onChange={setField('name')} autoComplete="name" />
            </Field>
            <Field label="E-mail" htmlFor="reg-email">
              <Input id="reg-email" type="email" value={values.email} onChange={setField('email')} autoComplete="email" />
            </Field>
            <Field label="Телефон" htmlFor="reg-phone">
              <Input id="reg-phone" type="tel" value={values.phone} onChange={setField('phone')} autoComplete="tel" />
            </Field>
          </Stack>
        )}

        {step === 1 && (
          <Stack direction="vertical" gap="md">
            <Field label="Страна" htmlFor="reg-country">
              <Input id="reg-country" value={values.country} onChange={setField('country')} autoComplete="country-name" />
            </Field>
            <Field label="Город" htmlFor="reg-city">
              <Input id="reg-city" value={values.city} onChange={setField('city')} autoComplete="address-level2" />
            </Field>
            <Field label="Улица, дом" htmlFor="reg-street">
              <Input id="reg-street" value={values.street} onChange={setField('street')} autoComplete="street-address" />
            </Field>
            <Field label="Индекс" htmlFor="reg-zip">
              <Input id="reg-zip" value={values.zip} onChange={setField('zip')} autoComplete="postal-code" />
            </Field>
          </Stack>
        )}

        {step === 2 && (
          <Stack direction="vertical" gap="sm">
            {summary.map(([label, value]) => (
              <Stack key={label} direction="horizontal" gap="md" justify="space-between">
                <Text tone="muted">{label}</Text>
                <Text>{value || '—'}</Text>
              </Stack>
            ))}
          </Stack>
        )}

        <Stack direction="horizontal" gap="sm" justify="space-between">
          <Button variant="secondary" disabled={step === 0} onClick={() => setStep((s) => s - 1)}>
            Назад
          </Button>
          {isLast ? (
            <Button variant="primary" onClick={() => onSubmit(values)}>
              Отправить
            </Button>
          ) : (
            <Button variant="primary" onClick={() => setStep((s) => s + 1)}>
              Дальше
            </Button>
          )}
        </Stack>
      </Stack>
    </Card>
  );
}

export default RegistrationWizard;

